//! The golden corpus (`docs/specs/vectorize-core.md` AC-01): the reference
//! implementation's output on the spec's test images and option sets,
//! generated by `tests/golden/generate.ts` from Vectorizer@32dd6c8.

use pincel_trace::{
    Mode, PotraceParams, Rgb, Threshold, TraceOptions, TraceResult, TraceSession, TurnPolicy,
};

use crate::geom::{Step, parse};
use crate::images::{self, Img};

const CORPUS: &str = include_str!("../golden/corpus.txt");

struct Case {
    name: String,
    image: String,
    options: TraceOptions,
    width: u32,
    height: u32,
    threshold: Option<u16>,
    stats: [u64; 4],
    layers: Vec<(String, Option<u64>, String)>,
}

fn image(name: &str) -> Img {
    match name {
        "disc" => images::disc(),
        "ring" => images::ring(),
        "rectangle" => images::rectangle(),
        "square_with_stray_pixel" => images::square_with_stray_pixel(),
        "four_colour" => images::four_colour(),
        "noisy_two_tone" => images::noisy_two_tone(),
        "speckled_two_tone" => images::speckled_two_tone(),
        "transparent_1x1" => images::transparent_1x1(),
        other => panic!("unknown image {other}"),
    }
}

fn options(spec: &str) -> TraceOptions {
    let kv: Vec<(&str, &str)> = spec
        .split(';')
        .map(|p| p.split_once('=').expect("key=value"))
        .collect();
    let get = |k: &str| kv.iter().find(|(key, _)| *key == k).map(|(_, v)| *v);
    let num = |k: &str| get(k).expect(k).parse::<f64>().expect(k);
    let flag = |k: &str| get(k) == Some("1");
    let mode = match get("mode") {
        Some("color") => Mode::Color {
            colors: num("colors") as u8,
            pinned: get("pinned").map(|p| {
                p.split(',')
                    .map(|h| Rgb::from_hex(h).expect("hex"))
                    .collect()
            }),
        },
        Some("mono") => Mode::Mono {
            threshold: match get("threshold") {
                Some("auto") => Threshold::Auto,
                _ => Threshold::Manual(num("threshold") as u8),
            },
            invert: flag("invert"),
            fill: Rgb::from_hex(get("fill").expect("fill")).expect("hex"),
        },
        other => panic!("unknown mode {other:?}"),
    };
    let turn_policy = match get("turn") {
        Some("black") => TurnPolicy::Black,
        Some("white") => TurnPolicy::White,
        Some("left") => TurnPolicy::Left,
        Some("right") => TurnPolicy::Right,
        Some("majority") => TurnPolicy::Majority,
        _ => TurnPolicy::Minority,
    };
    TraceOptions {
        mode,
        despeckle: flag("despeckle"),
        potrace: PotraceParams {
            turn_policy,
            min_area: num("min_area") as u32,
            alpha_max: num("alpha"),
            opt_curve: flag("optcurve"),
            opt_tolerance: num("tol"),
        },
    }
}

fn cases() -> Vec<Case> {
    let mut out: Vec<Case> = Vec::new();
    for line in CORPUS.lines() {
        if let Some(rest) = line.strip_prefix("case ") {
            let mut f = rest.split('|');
            let name = f.next().expect("name").to_string();
            let image = f.next().expect("image").to_string();
            out.push(Case {
                name,
                image,
                options: options(f.next().expect("options")),
                width: 0,
                height: 0,
                threshold: None,
                stats: [0; 4],
                layers: Vec::new(),
            });
        } else if let Some(rest) = line.strip_prefix("result ") {
            let c = out.last_mut().expect("case");
            let (head, stats) = rest.split_once('|').expect("result");
            let h: Vec<&str> = head.split(' ').collect();
            c.width = h[0].parse().expect("w");
            c.height = h[1].parse().expect("h");
            c.threshold = h[2].parse().ok();
            for (slot, v) in c.stats.iter_mut().zip(stats.split(' ')) {
                *slot = v.parse().expect("stat");
            }
        } else if let Some(rest) = line.strip_prefix("layer ") {
            let mut f = rest.splitn(3, ' ');
            let hex = f.next().expect("hex").to_string();
            let area = f.next().expect("area").parse().ok();
            let d = f.next().expect("d").to_string();
            out.last_mut().expect("case").layers.push((hex, area, d));
        }
    }
    out
}

/// Same commands, numbers within 0.001 (one step of the 3-decimal output).
fn assert_same_path(case: &str, got: &str, want: &str) {
    let (g, w) = (parse(got), parse(want));
    assert_eq!(g.len(), w.len(), "{case}: step count");
    let near = |a: f64, b: f64| (a - b).abs() <= 0.001 + 1e-9;
    for (i, (a, b)) in g.iter().zip(&w).enumerate() {
        let ok = match (a, b) {
            (Step::Move(x1, y1), Step::Move(x2, y2)) | (Step::Line(x1, y1), Step::Line(x2, y2)) => {
                near(*x1, *x2) && near(*y1, *y2)
            }
            (Step::Cubic(p), Step::Cubic(q)) => p.iter().zip(q).all(|(a, b)| near(*a, *b)),
            (Step::Close, Step::Close) => true,
            _ => false,
        };
        assert!(ok, "{case}: step {i} differs: {a:?} vs {b:?}");
    }
}

#[test]
fn golden_corpus_matches_the_reference() {
    let cases = cases();
    assert_eq!(cases.len(), 29, "corpus case count");
    for case in &cases {
        let img = image(&case.image);
        let r: TraceResult = TraceSession::new(&img.rgba, img.w, img.h)
            .expect("valid image")
            .trace(&case.options)
            .unwrap_or_else(|e| panic!("{}: {e}", case.name));
        let name = &case.name;
        assert_eq!((r.width, r.height), (case.width, case.height), "{name}");
        assert_eq!(r.threshold_used, case.threshold, "{name}: threshold");
        let s = r.stats;
        assert_eq!(
            [s.paths, s.segments, s.curves, s.lines],
            case.stats,
            "{name}: stats"
        );
        assert_eq!(r.layers.len(), case.layers.len(), "{name}: layer count");
        for (layer, (hex, area, d)) in r.layers.iter().zip(&case.layers) {
            assert_eq!(&layer.color.rgb().hex(), hex, "{name}: colour");
            if let Some(area) = area {
                assert_eq!(layer.area, *area, "{name}: area of {hex}");
            }
            assert_same_path(name, &layer.path_data, d);
        }
    }
}
